import {top,shell} from './screens.js';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function todayShanghai(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
export function companionDays(arrival,today=todayShanghai()){const parse=s=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))return NaN;const d=new Date(s+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===s?d.getTime():NaN};const days=(parse(today)-parse(arrival))/86400000;return Number.isFinite(days)&&days>=0?Math.floor(days)+1:null;}
export function petEditor(c){const p=c.pet;if(!p)return null;const input=(name,label,type='text')=>`<label class="pet-edit-field"><strong>${label}</strong><input name="${name}" aria-label="${label}" type="${type}" value="${E(p[name])}" ${name==='name'?'required maxlength="40"':type==='date'?`max="${todayShanghai()}"`:'maxlength="80"'}></label>`;const select=(name,label,items)=>`<label class="pet-edit-field"><strong>${label}</strong><select name="${name}" aria-label="${label}">${items.map(x=>`<option value="${x}" ${p[name]===x?'selected':''}>${x}</option>`).join('')}</select></label>`;return shell(top(c,'编辑宠物资料','profile')+`<form id="petEditForm" class="pet-edit-form" data-pet-id="${E(p.id)}">${input('name','名字')}${select('kind','种类',['猫咪','狗狗','其他'])}${input('breed','品种')}${select('sex','性别',['未知','公','母'])}${input('birthday','生日','date')}${input('arrival','到家日','date')}<label class="pet-edit-field"><strong>已绝育</strong><input name="neutered" type="checkbox" ${p.neutered?'checked':''}></label><p class="pet-edit-help">到家当天算陪伴第1天，天数会随日期更新。</p><button class="pet-edit-save" type="submit">保存资料</button></form>`,'petedit');}
